const raw = $input.first().json.content || $input.first().json.text || $input.first().json.message?.content;
let parsed;
try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { subject: 'Quick question', body: raw };
}
return [{
  json: {
    email: $('Split Out Leads').item.json.email,
    firstName: $('Split Out Leads').item.json.first_name,
    lastName: $('Split Out Leads').item.json.last_name,
    company: $('Split Out Leads').item.json.organization.name,
    domain: $('Split Out Leads').item.json.organization.primary_domain,
    title: $('Split Out Leads').item.json.title,
    subject: parsed.subject,
    body: parsed.body
  }
}];
